/* ==========================================================================
   Sell Your Gold and Silver in Los Angeles
   Scope: .ss-sell-gold-la — every selector below requires this class, which
   exists only in this page's markup.

   Spacing, backgrounds and borders live in WPBakery Design Options (matching
   the rest of the site). This file covers only what that tab cannot express:
   typography, flex/grid layout, gradient overlays, pseudo-elements, and every
   breakpoint. Responsive overrides of a Design Options value need !important,
   because WPBakery emits !important on the rules it generates.
   ========================================================================== */

.ss-sell-gold-la {
  --ssgla-gold: #c6973d;
  --ssgla-gold-32: rgba(198, 151, 61, 0.32);
  --ssgla-ink: #242424;
  --ssgla-body: #333333;
  --ssgla-navy: #010f6a;
}

/* Theme adds 35px under every element; sections control their own rhythm. */
.ss-sell-gold-la .wpb_content_element,
.ss-sell-gold-la .vc_custom_heading,
.ss-sell-gold-la .wpb_text_column {
  margin-bottom: 0;
}

/* ---------- typography ---------- */
.ss-sell-gold-la .ss-sell-gold-la__h2 {
  margin: 0 0 24px;
  font-size: 32px;
  line-height: 1.2;
  letter-spacing: 1px;
  color: var(--ssgla-ink);
}
.ss-sell-gold-la .ss-sell-gold-la__h2--center { text-align: center; }
.ss-sell-gold-la .ss-sell-gold-la__h2--navy { color: var(--ssgla-navy); }
.ss-sell-gold-la .ss-sell-gold-la__h2--flush { margin-bottom: 0; }

.ss-sell-gold-la .ss-sell-gold-la__lede p,
.ss-sell-gold-la .ss-sell-gold-la__section-lede p,
.ss-sell-gold-la .ss-sell-gold-la__areas-lede p,
.ss-sell-gold-la .ss-sell-gold-la__areas-foot p,
.ss-sell-gold-la .ss-sell-gold-la__intro p {
  margin: 0;
  font-size: 16px;
  line-height: 24px;
  color: var(--ssgla-body);
}

.ss-sell-gold-la .ss-sell-gold-la__intro {
  max-width: 984px;
  margin-inline: auto;
  text-align: center;
}
.ss-sell-gold-la .ss-sell-gold-la__section-lede { margin-top: -8px; }

/* ---------- gold pill button ---------- */
.ss-sell-gold-la .ss-sell-gold-la__btn { margin-bottom: 0; }
.ss-sell-gold-la .ss-sell-gold-la__btn .vc_general.vc_btn3 {
  padding: 10px 32px;
  border: 0;
  border-radius: 22px;
  background-color: var(--ssgla-gold);
  color: #fff;
  font-size: 16px;
  font-weight: 400;
  line-height: 24px;
  text-transform: none;
}
.ss-sell-gold-la .ss-sell-gold-la__btn .vc_general.vc_btn3:hover,
.ss-sell-gold-la .ss-sell-gold-la__btn .vc_general.vc_btn3:focus {
  background-color: #ac8231;
  color: #fff;
}

.ss-sell-gold-la .wpb_content_element figure,
.ss-sell-gold-la .vc_single_image-wrapper{
    width: 100%;
    display: block;
}

/* ---------- 2 — Why Sell to Us ---------- */
.ss-sell-gold-la__why-img img {
  width: 100%;
  height: auto;
  border-radius: 8px;
  display: block;
}
.ss-sell-gold-la__why-body .wpb_wrapper > * + * { margin-top: 24px; }

.ss-sell-gold-la__badges { margin: 0 -20px; }
.ss-sell-gold-la__badge .vc_column-inner { padding: 8px 12px; }
.ss-sell-gold-la__badge .ss-sell-gold-la__badge-v,
.ss-sell-gold-la__badge .ss-sell-gold-la__badge-l { display: block; }
.ss-sell-gold-la__badge .ss-sell-gold-la__badge-v {
  font-size: 20px;
  font-weight: 600;
  line-height: 1.2;
  color: var(--ssgla-ink);
}
.ss-sell-gold-la__badge .ss-sell-gold-la__badge-l {
  margin-top: 8px;
  font-size: 11px;
  line-height: 1.35;
  color: var(--ssgla-ink);
}

/* ---------- 3 — What We Buy cards ---------- */
.ss-sell-gold-la__card {
  position: relative;
  padding: 0 15px;
}
.ss-sell-gold-la__card > .vc_column-inner {
  position: relative;
  display: flex;
  align-items: flex-end;
  min-height: 333px;
  padding: 0;
  overflow: hidden;
    border: 1px solid rgba(198, 151, 61, 0.20);
    box-shadow: 0 4px 8px 0 rgba(0, 0, 0, 0.08);
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
}
.ss-sell-gold-la__card .wpb_wrapper { width: 100%; padding: 10px; }
/* Gradient sits on the innermost wrapper and is oversized, so it covers the
   photo whichever element WPBakery attaches the background to. */
.ss-sell-gold-la__card .wpb_wrapper::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to bottom,
    rgba(36, 36, 36, 0) 0%,
    rgba(36, 36, 36, 0.5) 62%,
    #242424 100%
  );
  pointer-events: none;
}
.ss-sell-gold-la__card-foot p {
  position: relative;
  display: flex;
  align-items: center;
  gap: 16px;
}
.ss-sell-gold-la__card-icon {
  flex: 0 0 36px;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--ssgla-gold);
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
}
.ss-sell-gold-la__card-icon img {
    width: 16px;
    height: 16px;
}

.ss-sell-gold-la__card-copy { display: block; min-width: 0; }
.ss-sell-gold-la__card-copy strong {
  display: block;
  font-size: 16px;
  font-weight: 600;
  color: #fff;
}
.ss-sell-gold-la__card-copy em {
  display: block;
  margin-top: 0;
  font-size: 14px;
  line-height: 22px;
  font-style: normal;
  color: #fff;
}

/* ---------- 4 — How It Works ---------- */
.ss-sell-gold-la__how-head { align-items: center; }
.ss-sell-gold-la__how-cta .vc_btn3-container { text-align: right; }

.ss-sell-gold-la__step { position: relative; }
.ss-sell-gold-la__step > .vc_column-inner { height: 100%; }
.ss-sell-gold-la__step-head {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px !important;
}
.ss-sell-gold-la__step-n {
  flex: 0 0 40px;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--ssgla-gold);
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  font-weight: 700;
}
.ss-sell-gold-la__step-head strong {
  font-size: 18px;
  font-weight: 600;
  color: var(--ssgla-ink);
}
.ss-sell-gold-la__step p {
  margin: 0;
  font-size: 16px;
  line-height: 24px;
  color: var(--ssgla-body);
}

.ss-sell-gold-la__steps {
    margin: 0 -20px !important;
}

.wpb_column.ss-sell-gold-la__step {
    padding: 0 40px;
}

/* dashed step connectors — decorative, desktop only */
@media (min-width: 992px) {
  .ss-sell-gold-la-how .ss-sell-gold-la__step {
	position: relative;
	z-index: 1;
}

.ss-sell-gold-la-how .ss-sell-gold-la__step:not(:last-child):after {
	content: '';
	position: absolute;
	top: 25px;
	right: -35px;
	background-image: url('/wp-content/uploads/2026/08/step-arrow.svg');
	background-size: contain;
	background-repeat: no-repeat;
	height: 120px;
	width: 65px;
	z-index: -1;
}
}

/* ---------- 5 — Visiting Our Store ---------- */
.ss-sell-gold-la-store-card { overflow: hidden; border-radius: 8px; }
.ss-sell-gold-la__storeinfo { position: relative; overflow: hidden; }
.ss-sell-gold-la__storeinfo > .vc_column-inner { position: relative; height: 100%; }
.ss-sell-gold-la__storeinfo .wpb_wrapper { position: relative; }
.ss-sell-gold-la__storeinfo .wpb_wrapper::before {
  content: "";
  position: absolute;
  inset: -80px;
  background: rgba(1, 15, 106, 0.86);
  pointer-events: none;
}
.ss-sell-gold-la__storeinfo .wpb_text_column { position: relative; }
.ss-sell-gold-la__storeinfo-title {
  margin: 0 0 24px;
  font-size: 28px;
  line-height: 1.2;
  color: #fff;
}
.ss-sell-gold-la__facts { margin: 0 0 10%; padding: 0; list-style: none; }
.ss-sell-gold-la__facts li {
  display: flex;
  gap: 16px;
  margin: 0 0 28px;
  color: #fff;
  font-size: 15px;
  line-height: 22px;
}
.ss-sell-gold-la__facts li i {
  flex: 0 0 44px;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.16);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
}
.ss-sell-gold-la__facts strong {
  display: block;
  margin-bottom: 4px;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.4px;
  text-transform: uppercase;
}
.ss-sell-gold-la__facts a { color: #fff; }
.ss-sell-gold-la__follow {
  position: relative;
  margin: 28px 0 12px;
  color: #fff;
  font-size: 15px;
  font-weight: 600;
}
.ss-sell-gold-la__follow::after {
  content: "";
  display: inline-block;
  width: 60px;
  height: 1px;
  margin-left: 12px;
  vertical-align: middle;
  background: rgba(255, 255, 255, 0.5);
}
.ss-sell-gold-la__social { position: relative; margin: 0; display: flex; gap: 12px; }
.ss-sell-gold-la__social a {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.16);
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
}
.ss-sell-gold-la__social a:hover { background: var(--ssgla-gold); color: #fff; }

.ss-sell-gold-la__map > .vc_column-inner,
.ss-sell-gold-la__map .wpb_wrapper,
.ss-sell-gold-la__map .wpb_gmaps_widget,
.ss-sell-gold-la__map .wpb_wrapper > div { height: 100%; }
.ss-sell-gold-la__map iframe { display: block; width: 100%; height: 100%; min-height: 420px; border: 0; }

/* ---------- 6 — Serving Los Angeles ---------- */
.ss-sell-gold-la .ss-sell-gold-la__areas-lede { margin-top: -4px; text-align: center; }
.ss-sell-gold-la .ss-sell-gold-la__areas-foot { margin-top: 32px; text-align: center; }
.ss-sell-gold-la .ss-sell-gold-la__areas ul {
  margin: 24px 0 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 16px 24px;
  justify-content: center;
}
.ss-sell-gold-la .ss-sell-gold-la__areas li {
  margin: 0;
  padding: 10px 32px;
  border-radius: 10px;
  background: var(--ssgla-gold);
  color: #fff;
  font-size: 16px;
  line-height: 24px;
}

/* ---------- 7 — FAQ ----------
   Panel gradient, radius and transparent heading/body come from the site-wide
   .ss-gradient-faq rules already in Additional CSS. Only the copy sizing here. */
.ss-sell-gold-la .ss-gradient-faq .vc_tta-panel-title { font-size: 18px; line-height: 1.4; }
.ss-sell-gold-la .ss-gradient-faq .vc_tta-panel-body p { margin: 0; font-size: 15px; line-height: 24px; }

/* ==========================================================================
   Responsive — WPBakery grid tiers: xs  .vc_column-inner { min-height: 300px; }
  .ss-sell-gold-la__storeinfo-title { font-size: 24px; }
}

/* tablet — stacked two-column sections must lose their side padding */
@media (max-width: 991px) {
  .ss-sell-gold-la.ss-sell-gold-la-why {
    padding-top: 48px !important;
    padding-bottom: 48px !important;
  }
  .wpb_column.ss-sell-gold-la__why-media {
    padding-right: 0 !important;
    margin-bottom: 32px;
  }
  .wpb_column.ss-sell-gold-la__why-body { padding-left: 0 !important; }
  .ss-sell-gold-la.ss-sell-gold-la-how {
    padding-top: 48px !important;
    padding-bottom: 48px !important;
  }
  .ss-sell-gold-la__step { margin-bottom: 16px; }
  .ss-sell-gold-la__how-cta .vc_btn3-container { text-align: left; margin-top: 16px; }
  .ss-sell-gold-la.ss-sell-gold-la-store-card { margin-bottom: 48px !important; }
  .ss-sell-gold-la__map iframe { min-height: 360px; }
}

@media (max-width: 767px) {
  .ss-sell-gold-la .ss-sell-gold-la__h2 { font-size: 24px; letter-spacing: 0.5px; }
  .ss-sell-gold-la.ss-sell-gold-la-intro { padding-top: 32px !important; }
  .ss-sell-gold-la.ss-sell-gold-la-why,
  .ss-sell-gold-la.ss-sell-gold-la-how {
    padding-top: 40px !important;
    padding-bottom: 40px !important;
  }
  .ss-sell-gold-la.ss-sell-gold-la-buy-cards,
  .ss-sell-gold-la.ss-sell-gold-la-areas,
  .ss-sell-gold-la.ss-sell-gold-la-faq-list { padding-bottom: 40px !important; }
  .ss-sell-gold-la.ss-sell-gold-la-store { padding-top: 40px !important; }

  /* badges: 2x2 instead of 4 across, and drop the vertical rules */
  .wpb_column.ss-sell-gold-la__badge {
    width: 50%;
    float: left;
    border-right-width: 0 !important;
  }
  .ss-sell-gold-la__badge .vc_column-inner { padding-left: 0; }

  .ss-sell-gold-la__card { margin-bottom: 16px; }
  .ss-sell-gold-la__card > .vc_column-inner { min-height: 260px; }
  .wpb_column.ss-sell-gold-la__storeinfo {
    padding-top: 0 !important;
    padding-right: 0 !important;
    padding-bottom: 0 !important;
    padding-left: 0 !important;
  }
  .ss-sell-gold-la__storeinfo > .vc_column-inner { padding: 28px; }
  .ss-sell-gold-la__map iframe { min-height: 300px; }
  .ss-sell-gold-la .ss-sell-gold-la__areas ul { gap: 12px; }
  .ss-sell-gold-la .ss-sell-gold-la__areas li { padding: 8px 20px; font-size: 15px; }
  .ss-sell-gold-la .ss-gradient-faq .vc_tta-panel-title { font-size: 16px; }
}

@media (prefers-reduced-motion: reduce) {
  .ss-sell-gold-la * { animation: none !important; transition: none !important; }
}

/* .inline-social-media */
.inline-social-media > .vc_column-inner > .wpb_wrapper {
    display: flex;
    gap: 14px;
}

.inline-social-media > .vc_column-inner > .wpb_wrapper .vc_icon_element {
    margin-bottom: 0;
}

.inline-social-media .vc_icon_element-inner {
    transition: .2s all ease-in-out;
}

.inline-social-media .vc_icon_element-inner:hover {
    transform: scale(1.2);
}

@media(min-width: 1025px) {
    .overlay-above-lg {
        position: relative;
    }

    .overlay-above-lg .vc_column-inner > .wpb_wrapper {
       position: relative;
       z-index: 1;
    }

    .overlay-above-lg:before {
        content: '';
        position: absolute;
        inset: 0;
        background-color: rgba(1, 15, 106, 0.85);
        z-index: 0;
    }
}

.ss-sell-gold-la__badges .ss-sell-gold-la__badge {
    position: relative;
}

.ss-sell-gold-la__badges .ss-sell-gold-la__badge {
    padding-inline: 10px;
}

.ss-sell-gold-la__badges .ss-sell-gold-la__badge:not(:last-child):after {
    content: '';
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    width: 1px;
    background-image: linear-gradient(90deg, rgba(198, 151, 61, 0.00) 0%, #C6973D 50%, rgba(198, 151, 61, 0.00) 100%);    
}

.store-information > .vc_column-inner {
    justify-content: center;
}

.ss-buy-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 32px;
}

.ss-buy-grid__card {
  background: #f8f9fa;
  border: 1px solid rgba(198, 151, 61, .35);
  border-radius: 8px;
  padding: 20px 24px;
  box-sizing: border-box;
}

.ss-buy-grid__title {
  font-family: Poppins, Arial, Helvetica, sans-serif;
  font-weight: 600;
  font-size: 18px;
  color: #242424;
  margin: 0 0 14px;
}

.ss-buy-grid__tiles {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin: 0;
  padding: 0;
}

.ss-buy-grid__tile {
  width: 64px;
  margin: 0;
  text-align: center;
}

.ss-buy-grid__tile img {
  width: 64px;
  height: 64px;
  object-fit: cover;
  border-radius: 6px;
  display: block;
}

.ss-buy-grid__tile figcaption {
  font-size: 11px;
  line-height: 1.3;
  color: #4b5563;
  margin-top: 6px;
}

@media (max-width: 991px) {
  .ss-buy-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 599px) {
  .ss-buy-grid {
    grid-template-columns: 1fr;
  }

  .ss-buy-grid__card {
    padding: 18px 20px;
  }
}
